-- ---------- type tree ----------
insert into public.classification_nodes(org_id, tree, parent_id, name, code, sort)
select '2ffdf0eb-e29b-48c3-8e72-f56b4620586d', 'type', null, w.name, w.code,
       (select coalesce(max(sort),0) from public.classification_nodes where org_id = '2ffdf0eb-e29b-48c3-8e72-f56b4620586d' and tree = 'type') + row_number() over (order by w.name)
from (select l1 as name, max(case when coalesce(l2,'') = '' and coalesce(l3,'') = '' then code end) as code
      from imp_nodes where tree = 'type' group by l1) w
where not exists (select 1 from public.classification_nodes n
                  where n.org_id = '2ffdf0eb-e29b-48c3-8e72-f56b4620586d' and n.tree = 'type' and n.parent_id is null and lower(n.name) = lower(w.name));
insert into public.classification_nodes(org_id, tree, parent_id, name, code, sort)
select '2ffdf0eb-e29b-48c3-8e72-f56b4620586d', 'type', p.id, w.name, w.code,
       (select coalesce(max(sort),0) from public.classification_nodes where org_id = '2ffdf0eb-e29b-48c3-8e72-f56b4620586d' and tree = 'type') + row_number() over (order by w.l1, w.name)
from (select l1, l2 as name, max(case when coalesce(l3,'') = '' then code end) as code
      from imp_nodes where tree = 'type' and coalesce(l2,'') <> '' group by l1, l2) w
join public.classification_nodes p
  on p.org_id = '2ffdf0eb-e29b-48c3-8e72-f56b4620586d' and p.tree = 'type' and p.parent_id is null and lower(p.name) = lower(w.l1)
where not exists (select 1 from public.classification_nodes n
                  where n.org_id = '2ffdf0eb-e29b-48c3-8e72-f56b4620586d' and n.tree = 'type' and n.parent_id = p.id and lower(n.name) = lower(w.name));
insert into public.classification_nodes(org_id, tree, parent_id, name, code, sort)
select '2ffdf0eb-e29b-48c3-8e72-f56b4620586d', 'type', p2.id, w.name, w.code,
       (select coalesce(max(sort),0) from public.classification_nodes where org_id = '2ffdf0eb-e29b-48c3-8e72-f56b4620586d' and tree = 'type') + row_number() over (order by w.l1, w.l2, w.name)
from (select l1, l2, l3 as name, max(code) as code
      from imp_nodes where tree = 'type' and coalesce(l3,'') <> '' group by l1, l2, l3) w
join public.classification_nodes p1
  on p1.org_id = '2ffdf0eb-e29b-48c3-8e72-f56b4620586d' and p1.tree = 'type' and p1.parent_id is null and lower(p1.name) = lower(w.l1)
join public.classification_nodes p2
  on p2.org_id = '2ffdf0eb-e29b-48c3-8e72-f56b4620586d' and p2.tree = 'type' and p2.parent_id = p1.id and lower(p2.name) = lower(w.l2)
where not exists (select 1 from public.classification_nodes n
                  where n.org_id = '2ffdf0eb-e29b-48c3-8e72-f56b4620586d' and n.tree = 'type' and n.parent_id = p2.id and lower(n.name) = lower(w.name));
-- ---------- family tree ----------
insert into public.classification_nodes(org_id, tree, parent_id, name, code, sort)
select '2ffdf0eb-e29b-48c3-8e72-f56b4620586d', 'family', null, w.name, w.code,
       (select coalesce(max(sort),0) from public.classification_nodes where org_id = '2ffdf0eb-e29b-48c3-8e72-f56b4620586d' and tree = 'family') + row_number() over (order by w.name)
from (select l1 as name, max(case when coalesce(l2,'') = '' and coalesce(l3,'') = '' then code end) as code
      from imp_nodes where tree = 'family' group by l1) w
where not exists (select 1 from public.classification_nodes n
                  where n.org_id = '2ffdf0eb-e29b-48c3-8e72-f56b4620586d' and n.tree = 'family' and n.parent_id is null and lower(n.name) = lower(w.name));
insert into public.classification_nodes(org_id, tree, parent_id, name, code, sort)
select '2ffdf0eb-e29b-48c3-8e72-f56b4620586d', 'family', p.id, w.name, w.code,
       (select coalesce(max(sort),0) from public.classification_nodes where org_id = '2ffdf0eb-e29b-48c3-8e72-f56b4620586d' and tree = 'family') + row_number() over (order by w.l1, w.name)
from (select l1, l2 as name, max(case when coalesce(l3,'') = '' then code end) as code
      from imp_nodes where tree = 'family' and coalesce(l2,'') <> '' group by l1, l2) w
join public.classification_nodes p
  on p.org_id = '2ffdf0eb-e29b-48c3-8e72-f56b4620586d' and p.tree = 'family' and p.parent_id is null and lower(p.name) = lower(w.l1)
where not exists (select 1 from public.classification_nodes n
                  where n.org_id = '2ffdf0eb-e29b-48c3-8e72-f56b4620586d' and n.tree = 'family' and n.parent_id = p.id and lower(n.name) = lower(w.name));
insert into public.classification_nodes(org_id, tree, parent_id, name, code, sort)
select '2ffdf0eb-e29b-48c3-8e72-f56b4620586d', 'family', p2.id, w.name, w.code,
       (select coalesce(max(sort),0) from public.classification_nodes where org_id = '2ffdf0eb-e29b-48c3-8e72-f56b4620586d' and tree = 'family') + row_number() over (order by w.l1, w.l2, w.name)
from (select l1, l2, l3 as name, max(code) as code
      from imp_nodes where tree = 'family' and coalesce(l3,'') <> '' group by l1, l2, l3) w
join public.classification_nodes p1
  on p1.org_id = '2ffdf0eb-e29b-48c3-8e72-f56b4620586d' and p1.tree = 'family' and p1.parent_id is null and lower(p1.name) = lower(w.l1)
join public.classification_nodes p2
  on p2.org_id = '2ffdf0eb-e29b-48c3-8e72-f56b4620586d' and p2.tree = 'family' and p2.parent_id = p1.id and lower(p2.name) = lower(w.l2)
where not exists (select 1 from public.classification_nodes n
                  where n.org_id = '2ffdf0eb-e29b-48c3-8e72-f56b4620586d' and n.tree = 'family' and n.parent_id = p2.id and lower(n.name) = lower(w.name));
update public.classification_nodes n set code = f.code
from (
  select i.tree, i.code,
         case when coalesce(i.l3,'') <> '' then 3 when coalesce(i.l2,'') <> '' then 2 else 1 end as depth,
         i.l1, i.l2, i.l3
  from imp_nodes i where coalesce(i.code,'') <> ''
) f
where n.org_id = '2ffdf0eb-e29b-48c3-8e72-f56b4620586d' and n.tree = f.tree and coalesce(n.code,'') = ''
  and (
    (f.depth = 1 and n.parent_id is null and lower(n.name) = lower(f.l1))
    or (f.depth = 2 and lower(n.name) = lower(f.l2) and exists (
          select 1 from public.classification_nodes p where p.id = n.parent_id and p.parent_id is null and lower(p.name) = lower(f.l1)))
    or (f.depth = 3 and lower(n.name) = lower(f.l3) and exists (
          select 1 from public.classification_nodes p join public.classification_nodes g on g.id = p.parent_id
          where p.id = n.parent_id and lower(p.name) = lower(f.l2) and g.parent_id is null and lower(g.name) = lower(f.l1)))
  );
commit;
